import{c as o,Q as t,j as r,m as a}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Controls and radio controls","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/controls-and-radio-controls.md","filePath":"user/event-setup/controls-and-radio-controls.md"}'),n={name:"user/event-setup/controls-and-radio-controls.md"};function s(i,e,l,c,h,d){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="controls-and-radio-controls" tabindex="-1">Controls and radio controls <a class="header-anchor" href="#controls-and-radio-controls" aria-label="Permalink to &quot;Controls and radio controls&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers setting up timing points.</p><p>In Manager a control carries one or more control codes. A <strong>radio control</strong> is one whose punches also report back live during the event, so they surface on Spectator, Leaderboard and Commentary as runners pass through.</p><p>This page covers how Manager models controls, how radio controls work, the special Start / Finish / Check controls, and how to create, edit, and manage all of them. As with classes and courses, most events get their controls from an import — see <a href="./import-event-data">Importing event data</a> — so usually you&#39;re reviewing and marking radios rather than entering controls from scratch.</p><h2 id="two-kinds-of-control" tabindex="-1">Two kinds of control <a class="header-anchor" href="#two-kinds-of-control" aria-label="Permalink to &quot;Two kinds of control&quot;">​</a></h2><p>Manager models <strong>normal controls</strong> and the <strong>special controls</strong> — Start, Finish, and Check — differently:</p><ul><li><strong>Normal controls</strong> carry one or more <em>control codes</em> and are matched to a punch by code.</li><li><strong>Start, Finish and Check controls</strong> carry <strong>no code of their own</strong> in Manager. They anchor courses by position for card downloads. There are <em>event level</em> codes, which are used to resolve these special controls when triggered as radios punches — see <a href="#start-finish-and-check-codes">Start, Finish and Check codes</a> below.</li></ul><p>The split matters because a Start, Finish or Check punch from a download carries <em>no</em> course code — only the fact that it happened. Radio punches from Start, Finish and Check <em>only</em> carry a code — so Manager has to map that code to the special meaning. Everything else is treated as a normal control along the course.</p><blockquote><p><strong>Note:</strong> Manager accepts normal control codes from <strong>31 to 511</strong> — 1–30 are reserved for SportIdent&#39;s special stations.</p></blockquote><h2 id="the-controls-page" tabindex="-1">The Controls page <a class="header-anchor" href="#the-controls-page" aria-label="Permalink to &quot;The Controls page&quot;">​</a></h2><p>Navigate to <strong>Controls</strong> in the <strong>Event Data</strong> section of the side menu.</p><p>The table shows one row per control:</p><ul><li><strong>Control</strong> — the control name. Click it (or the pencil icon) to open the <strong>Edit Control</strong> dialog.</li><li><strong>Control Codes</strong> — the code(s) this control uses. Start, Finish and Check controls show <em>None configured</em> here, since they carry no code. If a <a href="#renumbered-or-swapped-controls">replacement code</a> has been set, the original code appears struck through with the replacement beside it.</li><li><strong>Is Radio</strong> — a toggle showing whether this control reports radio punches. Not applicable to Start / Finish / Check.</li><li><strong>Radio Name</strong> — an optional custom display name used on Leaderboard and Commentary.</li><li><strong>Time Offset</strong> — any clock correction applied to this control&#39;s punches, shown as <code>+HH:MM:SS</code>.</li><li><strong>Number of Courses</strong> — how many courses use this control. Click to see the list.</li></ul><p>Filter the table with <strong>Search Control</strong> (by name) or the <strong>Is Radio</strong> filter (Yes / No).</p><p>The <strong>Actions</strong> menu (top right) has:</p><ul><li><strong>Add control</strong> — create a new control (see below).</li><li><strong>Leg distances</strong> — open the shared leg-distances editor (the same editor reachable from the Courses page; see <a href="./classes-and-courses#leg-distances">Leg distances</a>).</li></ul><h2 id="creating-a-control-by-hand" tabindex="-1">Creating a control by hand <a class="header-anchor" href="#creating-a-control-by-hand" aria-label="Permalink to &quot;Creating a control by hand&quot;">​</a></h2><p>Click <strong>Actions → Add control</strong>. The <strong>Add Control</strong> dialog opens.</p><p><strong>Fields:</strong></p><ul><li><strong>Type</strong> — required. Choose <strong>Normal</strong>, <strong>Start</strong>, or <strong>Finish</strong>. (There&#39;s no <strong>Check</strong> option — every event is seeded with a single, permanent Check control.)</li><li><strong>Control Code</strong> — shown for Normal controls only, and required. Enter a number from <strong>31 to 511</strong>. Manager rejects a code that&#39;s out of range or already used by another control.</li></ul><p>Manager names the control automatically: a Normal control takes its code as its name, while Start / Finish controls auto-number — <code>Start</code>, then <code>Start 2</code>, <code>Start 3</code>, … as you add more. To give a Start or Finish a custom name, rename it afterwards on the <strong>Edit Control</strong> dialog&#39;s <strong>Name</strong> tab.</p><p>Click <strong>Add</strong>.</p><blockquote><p><strong>Tip:</strong> You rarely need to add Normal controls here first — when you build a course on the Courses page you can type a control code straight into the course and Manager creates the control if it doesn&#39;t exist yet. Use <strong>Add control</strong> mainly to add an extra <strong>Start</strong> or <strong>Finish</strong> for a split-start or two-finish event.</p></blockquote><h2 id="editing-a-control" tabindex="-1">Editing a control <a class="header-anchor" href="#editing-a-control" aria-label="Permalink to &quot;Editing a control&quot;">​</a></h2><p>Click a control&#39;s name (or its pencil icon) to open the <strong>Edit Control</strong> dialog. Which tabs appear depends on the control&#39;s type:</p><table tabindex="0"><thead><tr><th>Control type</th><th>Tabs available</th></tr></thead><tbody><tr><td><strong>Normal</strong></td><td>Radio, Replacement, Time Offset, Faulty</td></tr><tr><td><strong>Start / Finish</strong></td><td>Name, Time Offset</td></tr><tr><td><strong>Check</strong></td><td>Time Offset only</td></tr></tbody></table><h3 id="name-start-finish-only" tabindex="-1">Name (Start / Finish only) <a class="header-anchor" href="#name-start-finish-only" aria-label="Permalink to &quot;Name (Start / Finish only)&quot;">​</a></h3><p>Rename the control. Names must be unique within their type (no two Starts can share a name). Normal controls aren&#39;t renamed here — they&#39;re identified by their code.</p><h3 id="radio-normal-only" tabindex="-1">Radio (Normal only) <a class="header-anchor" href="#radio-normal-only" aria-label="Permalink to &quot;Radio (Normal only)&quot;">​</a></h3><p>This is where you make a control a radio control:</p><ul><li><strong>Is Radio</strong> — toggle on to have this control&#39;s punches reported live. <em>Radio controls are shown on Leaderboard and Commentary screens for classes that use them.</em></li><li><strong>Radio Name</strong> — an optional friendly display name (e.g. &quot;Spectator control&quot;, &quot;Last control&quot;). Leave it blank to use the control&#39;s code.</li></ul><p>You can also flip <strong>Is Radio</strong> directly from the toggle in the <strong>Is Radio</strong> column on the Controls page, without opening the dialog.</p><blockquote><p><strong>Tip:</strong> With <strong>Auto-mark controls as radio controls</strong> enabled (the default — see <a href="#auto-marking-controls-as-radios">Auto-marking controls as radios</a> below), you often don&#39;t need to set <strong>Is Radio</strong> by hand at all: the first live punch from a control flips it on for you.</p></blockquote><h3 id="replacement-normal-only" tabindex="-1">Replacement (Normal only) <a class="header-anchor" href="#replacement-normal-only" aria-label="Permalink to &quot;Replacement (Normal only)&quot;">​</a></h3><ul><li><strong>Replacement Code</strong> — <em>Alternative code if this control was replaced during the event with a station using a different number.</em> See <a href="#renumbered-or-swapped-controls">Renumbered or swapped controls</a> below.</li></ul><h3 id="time-offset" tabindex="-1">Time Offset <a class="header-anchor" href="#time-offset" aria-label="Permalink to &quot;Time Offset&quot;">​</a></h3><ul><li>A cumulative correction applied to <strong>every</strong> punch recorded against this control — card downloads and radio punches alike. Set a sign (<strong>+</strong> or <strong>−</strong>) and enter <strong>Hours</strong>, <strong>Minutes</strong>, and <strong>Seconds</strong> (up to 24 hours). <strong>Reset offset</strong> clears it.</li><li>Use this when a control&#39;s internal clock has drifted, was set incorrectly, or wasn&#39;t adjusted for daylight saving. The correction is applied retrospectively, so fixing the offset after downloads have come in re-times the affected punches.</li></ul><h3 id="faulty-normal-only" tabindex="-1">Faulty (Normal only) <a class="header-anchor" href="#faulty-normal-only" aria-label="Permalink to &quot;Faulty (Normal only)&quot;">​</a></h3><ul><li><strong>Control is faulty (non-functional)</strong> — toggle on when a control&#39;s unit <strong>failed during the event</strong> and some competitors couldn&#39;t punch it. The control is then <strong>never required</strong>: missing it is never a Missing Punch, on every course, for downloads already processed as well as those still to come.</li><li><strong>It keeps its place in the course.</strong> Competitors still ran to it and past it, so it stays in the control sequence — the course length still measures through it, and it still gets its own numbered row in splits printouts, results exports and analysis. That&#39;s what keeps the control numbers a competitor reads on their splits matching the ones printed on their map. A competitor who <em>did</em> punch it before it failed keeps that split time; one who couldn&#39;t simply has a blank there.</li><li><strong>Live radio passings for it are still ignored</strong> — a failed unit shouldn&#39;t report competitors through it on the tracking and commentary screens.</li><li>Marking a control faulty <strong>clears its replacement code and time offset</strong> (those tabs are disabled while it&#39;s on) — neither applies to a unit that has failed.</li><li>Use this when a unit dies mid-event and isn&#39;t replaced. If you instead swapped in a working unit with a <em>different</em> code, set a <a href="#replacement-normal-only">Replacement</a> instead, so punches on the new code still count.</li></ul><h2 id="marking-radio-controls-and-setting-their-priority" tabindex="-1">Marking radio controls and setting their priority <a class="header-anchor" href="#marking-radio-controls-and-setting-their-priority" aria-label="Permalink to &quot;Marking radio controls and setting their priority&quot;">​</a></h2><h3 id="why-mark-radio-controls-—-and-why-prioritise-them" tabindex="-1">Why mark radio controls — and why prioritise them <a class="header-anchor" href="#why-mark-radio-controls-—-and-why-prioritise-them" aria-label="Permalink to &quot;Why mark radio controls — and why prioritise them&quot;">​</a></h3><p><strong>More radios is better.</strong> There&#39;s no downside to having lots of radio controls on a course — the more points a course reports from, the more Manager has to work with:</p><ul><li><strong>Better predictions.</strong> With more splits coming in, Manager has more data to project finish times and standings, so its live predictions are sharper.</li><li><strong>A better view for commentators.</strong> Each extra radio is another vantage point on the race. Commentators can see how competitors are doing through the course and how the race is unfolding, rather than guessing between sparse splits.</li><li><strong>Safety.</strong> Frequent radio reports mean you can see who&#39;s out on the course and roughly where they are — useful for spotting a competitor who&#39;s overdue or has stopped reporting.</li></ul><p>So mark every control that has a radio station on it (or let Manager do it for you — see <a href="#auto-marking-controls-as-radios">Auto-marking controls as radios</a>).</p><p><strong>Priority is about the screen, not the data.</strong> Marking lots of radios doesn&#39;t crowd your displays, because the priority is a separate decision. Leaderboard screens have limited room, so in practice you only want about <strong>3 or 4</strong> radio controls shown per course — maybe a few more for elite courses where there&#39;s more interest. The priority is how <em>you</em> choose which of your many radios win that limited space, rather than leaving it to Manager. Capture everything live, then promote just the most important controls (arena passes, run-ins, the last control) to <strong>High</strong> and hide the rest.</p><h3 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h3><p>Making a control a radio control is a two-step idea:</p><ol><li><strong>Mark the control as a radio</strong> — the <strong>Is Radio</strong> flag on the control (above). This tells Manager the control reports live punches. Manager can also set this for you automatically as punches arrive — see <a href="#auto-marking-controls-as-radios">Auto-marking controls as radios</a> below.</li><li><strong>Choose how each class displays it</strong> — done per class on the <a href="./classes-and-courses#the-classes-page">Classes</a> page, in the <strong>Radio Controls (including priority)</strong> column.</li></ol><p>A radio control only appears for the classes whose courses actually pass through it. On the Classes page each such control shows as a chip with a <strong>priority</strong> selector:</p><ul><li><strong>High</strong></li><li><strong>Medium</strong></li><li><strong>Low</strong></li><li><strong>Hide</strong></li></ul><p>Leaderboard has a <strong>Max Radio Controls</strong> setting that limits how many radio controls a screen shows at once, so the priority decides <em>which</em> radio controls win that space for a given class. Set the spectator-facing controls (arena passes, run-ins) to <strong>High</strong>, and <strong>Hide</strong> any you don&#39;t want on screen for that class.</p><p>For relay classes the radio controls are grouped by leg (<strong>Leg 1</strong>, <strong>Leg 2</strong>, …), so you can give each leg its own set of live splits.</p><blockquote><p><strong>Note:</strong> A normal control can be shared by many courses and classes. Marking it as a radio once makes it available everywhere it&#39;s used — you then tune its priority class by class.</p></blockquote><h2 id="auto-marking-controls-as-radios" tabindex="-1">Auto-marking controls as radios <a class="header-anchor" href="#auto-marking-controls-as-radios" aria-label="Permalink to &quot;Auto-marking controls as radios&quot;">​</a></h2><p>You usually don&#39;t have to tick <strong>Is Radio</strong> for each control by hand. By default Manager marks a control as a radio control automatically the first time a live radio punch arrives for it — so as your radio stations come online during the event, the controls they sit on light up on their own and start appearing in live tracking, Leaderboard and Commentary.</p><p>This is controlled by an <strong>event-level</strong> setting. Open the event dashboard, click <strong>Edit</strong> (event details), and go to the <strong>Radio Controls</strong> tab:</p><ul><li><strong>Auto-mark controls as radio controls</strong> — on by default. <em>When a radio punch arrives for a course control, automatically mark that control as a radio control so it appears in live tracking, Leaderboard, Commentary, etc — no need to tick each one by hand.</em></li></ul><p>Turn it <strong>off</strong> if you&#39;d rather choose your radio controls deliberately — for example when some controls report punches that you don&#39;t want surfaced as live splits. With it off, only the controls you&#39;ve marked <strong>Is Radio</strong> yourself are treated as radios. Only normal course controls are auto-marked; Start, Finish and Check punches never trigger it (those are resolved by the event&#39;s code lists — see <a href="#start-finish-and-check-codes">Start, Finish and Check codes</a> below).</p><h2 id="start-finish-and-check-codes" tabindex="-1">Start, Finish and Check codes <a class="header-anchor" href="#start-finish-and-check-codes" aria-label="Permalink to &quot;Start, Finish and Check codes&quot;">​</a></h2><p>Because Start, Finish and Check radio punches just carry a code (no special meaning), Manager needs to know which codes represent these special punches. These lists live on the event itself, not on the controls.</p><h3 id="why-these-mappings-matter" tabindex="-1">Why these mappings matter <a class="header-anchor" href="#why-these-mappings-matter" aria-label="Permalink to &quot;Why these mappings matter&quot;">​</a></h3><p>Downloads and radio punches tell Manager about Start, Finish and Check in <strong>opposite</strong> ways:</p><ul><li><strong>A card download</strong> records the <em>special meaning</em> — the card itself knows this punch was a Start, a Finish or a Check — but doesn&#39;t need a course code to convey it. Manager reads the meaning straight off the card.</li><li><strong>A radio punch</strong> carries <em>only the code</em> the unit was programmed with, never the special meaning. A radio punch of code <code>1</code> is just &quot;code 1&quot; on the wire — Manager has no way to know that&#39;s your Start unit unless <strong>you tell it</strong>.</li></ul><p>That&#39;s the whole reason these lists exist. Event operators program their Start, Finish and Check units with a code of their choosing — for example <strong>Start = 1, Finish = 2, Check = 3</strong> — using SportIdent&#39;s <strong>SiConfig+</strong> application. Any code from <strong>1 to 13</strong> can be used for these special stations. Whatever you chose there, you must mirror here so Manager can translate the radio punches.</p><blockquote><p><strong>Important:</strong> If your Start unit is programmed as code <code>1</code> and it sends radio punches, you <strong>must</strong> list <code>1</code> under <strong>Start Codes</strong>. Otherwise Manager sees a radio punch of code <code>1</code>, finds it in none of the three lists, and treats it as a regular control along the course — runners appear to &quot;punch&quot; a phantom control instead of starting. Getting these mappings right is what makes live Start/Finish/Check work.</p></blockquote><h3 id="setting-the-codes" tabindex="-1">Setting the codes <a class="header-anchor" href="#setting-the-codes" aria-label="Permalink to &quot;Setting the codes&quot;">​</a></h3><p>Open the event dashboard, click <strong>Edit</strong> (event details), and go to the <strong>Radio Controls</strong> tab. You&#39;ll find three fields:</p><ul><li><strong>Start Codes</strong></li><li><strong>Finish Codes</strong></li><li><strong>Check Codes</strong></li></ul><p>Enter comma-separated codes in each (you can list more than one per field if you run several units with different codes). As the dialog explains: <em>Radio Control punches are only transmitted with the control code, not a &quot;Start&quot;, &quot;Finish&quot; or &quot;Check&quot; punch. Configure the codes that you use for these units so that meshO Manager can interpret the radio punches correctly. Any other codes are treated as regular radio controls along the course.</em></p><p>In other words: a radio punch arriving on a code listed under <strong>Finish Codes</strong> is read as a finish punch; a code that&#39;s in none of the three lists is read as a normal control along the course. Card downloads carry the special meaning directly, so these lists matter only for radio punches.</p><h2 id="multiple-start-finish-and-check-controls" tabindex="-1">Multiple Start, Finish and Check controls <a class="header-anchor" href="#multiple-start-finish-and-check-controls" aria-label="Permalink to &quot;Multiple Start, Finish and Check controls&quot;">​</a></h2><p>An event can have <strong>more than one</strong> Start or Finish — for split starts, a separate finish chute, multiple Check stations, and so on. Each course independently picks <strong>its</strong> Start and Finish in the <a href="./classes-and-courses#creating-a-course-by-hand">Edit Course dialog</a>, so a map with two starts imports as courses anchored at different Start controls. The Start / Finish dropdowns there list exactly the Start and Finish controls you&#39;ve defined.</p><p>When you add a Start or Finish, the <strong>Add Control</strong> dialog auto-numbers it (<code>Start</code>, <code>Start 2</code>, <code>Start 3</code>, …); you can rename it afterwards on the <strong>Edit Control</strong> dialog&#39;s <strong>Name</strong> tab. You can&#39;t delete the <strong>last</strong> Start or Finish — an event must always keep at least one of each — and you can&#39;t delete a Start or Finish that a course still uses until those courses are reassigned. The Check control is permanent: it can&#39;t be renamed or deleted, only given a time offset.</p><h2 id="how-controls-relate-to-courses-and-classes" tabindex="-1">How controls relate to courses and classes <a class="header-anchor" href="#how-controls-relate-to-courses-and-classes" aria-label="Permalink to &quot;How controls relate to courses and classes&quot;">​</a></h2><ul><li><strong>Courses</strong> anchor to a Start and a Finish (by identity, not code) and hold an ordered list of the normal control codes in between. A normal control is shown as used by a course when one of its codes appears in that course. See <a href="./classes-and-courses">Classes and courses</a>.</li><li><strong>Classes</strong> inherit their radio controls from the courses assigned to them: a class shows the radio controls that lie on its course(s), and you set the display priority per class.</li><li><strong>Shared controls</strong> are the norm — the same physical control (and the same code) is reused across many courses, and Manager keeps a single control for it. The <strong>Number of Courses</strong> column shows how widely a control is used.</li></ul><h2 id="renumbered-or-swapped-controls" tabindex="-1">Renumbered or swapped controls <a class="header-anchor" href="#renumbered-or-swapped-controls" aria-label="Permalink to &quot;Renumbered or swapped controls&quot;">​</a></h2><p>If a control&#39;s physical station is swapped mid-event for one with a different number — or the wrong unit was put out — you don&#39;t have to edit every course. Instead, open the control&#39;s <strong>Replacement</strong> tab and set a <strong>Replacement Code</strong>. Manager then accepts punches on the new code as if they were on the original, so existing courses and results stay valid. The Controls page shows the original code struck through with the replacement beside it.</p><h2 id="deleting-all-controls" tabindex="-1">Deleting all controls <a class="header-anchor" href="#deleting-all-controls" aria-label="Permalink to &quot;Deleting all controls&quot;">​</a></h2><p><strong>Actions → Delete all controls</strong> clears the controls list in one step — useful when a course import created a set of controls you&#39;d rather rebuild than correct.</p><p>Manager confirms first and lists what else changes:</p><ul><li>Only the <strong>normal</strong> controls go, along with their radio setting, radio name, replacement code and time offset.</li><li><strong>Start, Finish and Check are kept.</strong> Courses anchor to them by identity, and an event always needs at least one of each, so a delete-all never removes them. The confirmation reports how many were kept.</li><li>Courses keep their control codes. The controls themselves come back automatically the next time a course is saved or imported, so this is a way to reset the radio and timing settings without touching the courses.</li><li>Measured leg distances are kept, and apply again if the same controls come back.</li></ul><p>This cannot be undone. On a live event, <a href="./../reference/backup-and-restore">back the event up</a> first — and remember that clearing the radio settings stops radio punches from being matched until the controls are marked as radios again.</p><h2 id="leg-distances" tabindex="-1">Leg distances <a class="header-anchor" href="#leg-distances" aria-label="Permalink to &quot;Leg distances&quot;">​</a></h2><p>Distances between consecutive controls are kept in one shared bank for the whole event, keyed by the identity of the two controls. Edit them from <strong>Actions → Leg distances</strong> on the Controls page (the same editor is on the Courses page). Editing the distance for a leg once updates every course that traverses it. See <a href="./classes-and-courses#leg-distances">Leg distances</a> for the full explanation.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./classes-and-courses">Classes and courses</a> — how courses anchor to Start/Finish controls and how classes pick up radio controls</li><li><a href="./import-event-data">Importing event data</a> — the usual way controls get created</li><li><a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a> — bringing radio controls online during the event</li><li><a href="./../running-the-event/radio-punches">Radio punches</a> — the live feed of punches from radio controls</li><li><a href="./relay-events">Relay events</a> — per-leg radio controls on relay classes</li></ul>',86)])])}const p=o(n,[["render",s]]);export{u as __pageData,p as default};
